class Solution {
public:
    long long minimumReplacement(vector<int>& nums) {
        long long ans = 0;
        long long prev = nums.back();
        for (int i = nums.size() - 2; i >= 0; --i) {
            long long curr = nums[i];
            if (curr <= prev) {
                prev = curr;
            } else {
                long long k = (curr + prev - 1) / prev;
                ans += k - 1;
                prev = curr / k;
            }
        }
        return ans;
    }
};
